import React, { useRef, useCallback, useEffect, useState } from 'react';
import './Section.css';

/**
 * Reusable Section component for consistent resume sections.
 * Also wires up a scroll-reveal animation (IntersectionObserver) while still
 * exposing the underlying DOM node to the forwarded ref, so top-level
 * navigation (scrollToSection) keeps working unchanged.
 * @param {string} id - Section ID for navigation
 * @param {string} title - Section title
 * @param {string} eyebrow - Optional small kicker label above the title
 * @param {React.ReactNode} children - Section content
 * @param {React.Ref} ref - Forward ref for scroll navigation
 */
const Section = React.forwardRef(({ id, title, eyebrow, children, className = '' }, ref) => {
  const localRef = useRef(null);
  const [isVisible, setIsVisible] = useState(false);

  const setRefs = useCallback((node) => {
    localRef.current = node;
    if (typeof ref === 'function') {
      ref(node);
    } else if (ref) {
      ref.current = node;
    }
  }, [ref]);

  useEffect(() => {
    const node = localRef.current;
    if (!node || typeof IntersectionObserver === 'undefined') {
      setIsVisible(true);
      return undefined;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsVisible(true);
            observer.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.12, rootMargin: '0px 0px -60px 0px' }
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  return (
    <section
      id={id}
      ref={setRefs}
      className={`resume-section reveal ${isVisible ? 'is-visible' : ''} ${className}`.trim()}
    >
      {eyebrow && <span className="section-eyebrow">{eyebrow}</span>}
      {title && <h2 className="section-title">{title}</h2>}
      <div className="section-content">
        {children}
      </div>
    </section>
  );
});

Section.displayName = 'Section';

export default Section;
