import React from 'react';
import Section from '../Section/Section';
import SkillGroup from '../SkillGroup/SkillGroup';
import { SKILLS_DATA } from '../../constants';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';
import './SkillsSection.css';

/**
 * Skills section component with grouped skills
 */
const SkillsSection = React.forwardRef((props, ref) => {
    const { lang } = useLanguage();
    const t = content[lang].skills;

    return (
        <Section id="skills" title={t.sectionTitle} ref={ref}>
            <SkillGroup title={t.groups.languages} skills={SKILLS_DATA.languages} />
            <SkillGroup title={t.groups.frameworks} skills={SKILLS_DATA.frameworks} />
            <SkillGroup title={t.groups.tools} skills={SKILLS_DATA.tools} />
        </Section>
    );
});

SkillsSection.displayName = 'SkillsSection';

export default SkillsSection;
