import React from 'react';
import './AmbientBackground.css';

/**
 * AmbientBackground — a fixed, decorative backdrop that sits behind all page
 * content: slow-drifting colored mist plus small rising embers/spores, for a
 * subtle "Upside Down" atmosphere without getting in the way of readability.
 * Purely visual, so it's aria-hidden and ignores pointer events.
 */
const AmbientBackground = () => (
  <div className="ambient-background" aria-hidden="true">
    <div className="ambient-mist" />
    <div className="ambient-embers" />
  </div>
);

export default AmbientBackground;
