import React, { useState, useRef, useEffect } from 'react';
import './ResumeHeader.css';
import profileImage from '../../assets/profile-page.JPG';

/**
 * ResumeHeader — the compact "intro" content pinned inside the video hero:
 * profile photo, name, tagline and skill badges. Contact buttons render
 * immediately below this block (see HeroContactBar).
 * @param {string} name - Full name
 * @param {string} tagline - One-line value proposition below the name
 * @param {Array<string>} badges - Small tech/skill badges shown under the tagline
 */
const ResumeHeader = ({ name, tagline, badges = [] }) => {
  const [imageLoading, setImageLoading] = useState(true);
  const imageRef = useRef(null);

  useEffect(() => {
    // Ensure image is not draggable via DOM manipulation
    if (imageRef.current) {
      imageRef.current.setAttribute('draggable', 'false');
      imageRef.current.ondragstart = () => false;
      imageRef.current.ondrag = () => false;
      imageRef.current.ondragend = () => false;
    }
  }, [imageLoading]);

  const handleImageLoad = () => {
    setImageLoading(false);
  };

  const handleImageError = () => {
    setImageLoading(false);
  };

  const handleDragStart = (e) => {
    e.preventDefault();
    e.stopPropagation();
    return false;
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    return false;
  };

  const handleDragEnd = (e) => {
    e.preventDefault();
    e.stopPropagation();
    return false;
  };

  const handleContextMenu = (e) => {
    e.preventDefault();
    e.stopPropagation();
    return false;
  };

  const handleMouseDown = (e) => {
    // Prevent image selection
    e.preventDefault();
    return false;
  };

  const handleSelectStart = (e) => {
    e.preventDefault();
    return false;
  };

  return (
    <header className="resume-header">
      <div className="resume-header-content">
        <div
          className="profile-image-container"
          onDragStart={(e) => e.preventDefault()}
          onDrag={(e) => e.preventDefault()}
          onDragEnd={(e) => e.preventDefault()}
          onContextMenu={(e) => e.preventDefault()}
        >
          {imageLoading && (
            <div className="image-loader">
              <div className="loader-spinner"></div>
            </div>
          )}
          <img
            ref={imageRef}
            src={profileImage}
            alt={name}
            className={`profile-image ${imageLoading ? 'image-loading' : ''}`}
            draggable={false}
            onDragStart={handleDragStart}
            onDrag={handleDrag}
            onDragEnd={handleDragEnd}
            onContextMenu={handleContextMenu}
            onMouseDown={handleMouseDown}
            onSelectStart={handleSelectStart}
            onLoad={handleImageLoad}
            onError={handleImageError}
          />
        </div>
        <h1 className="resume-name">{name}</h1>
        {tagline && <p className="hero-tagline">{tagline}</p>}
        {badges.length > 0 && (
          <div className="hero-badges">
            {badges.map((badge) => (
              <span className="hero-badge" key={badge}>{badge}</span>
            ))}
          </div>
        )}
      </div>
    </header>
  );
};

export default ResumeHeader;
