import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Swiper, SwiperSlide } from 'swiper/react';
import { EffectCoverflow, Navigation, Pagination } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/effect-coverflow';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import Section from '../Section/Section';
import { CORE_PROJECTS } from '../../constants';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';
import './ProjectsSection.css';

const PROJECT_KEYS = ['cr', 'abs', 'nlp', 'weetbis'];

const ProjectsSection = React.forwardRef((props, ref) => {
  const navigate = useNavigate();
  const { lang } = useLanguage();
  const t = content[lang].projects;

  const handleCardClick = (key) => {
    navigate(`/projects/${key}`);
  };

  return (
    <Section id="projects" title={t.sectionTitle} ref={ref}>
      <div className="projects-carousel-wrapper">
        <Swiper
          modules={[EffectCoverflow, Navigation, Pagination]}
          effect="coverflow"
          grabCursor
          centeredSlides
          slidesPerView="auto"
          coverflowEffect={{
            rotate: 0,
            stretch: 50,
            depth: 180,
            modifier: 1.2,
            slideShadows: false,
          }}
          navigation
          pagination={{ clickable: true }}
          className="projects-swiper"
        >
          {PROJECT_KEYS.map((key) => {
            const proj = CORE_PROJECTS[key];
            const projContent = t.items[key];
            return (
              <SwiperSlide key={key} className="projects-swiper-slide">
                <button
                  className="project-card"
                  onClick={() => handleCardClick(key)}
                  aria-label={`View ${projContent.title}`}
                >
                  <div className="project-card-img-placeholder">
                    <span className="project-card-img-label">
                      {projContent.title}
                    </span>
                  </div>
                  <div className="project-card-body">
                    <h3 className="project-card-title">{projContent.title}</h3>
                    <p className="project-card-description">{projContent.description}</p>
                    <div className="project-card-stack">
                      {proj.stack.slice(0, 4).map((tech) => (
                        <span className="project-card-tag" key={tech}>{tech}</span>
                      ))}
                      {proj.stack.length > 4 && (
                        <span className="project-card-tag project-card-tag-more">
                          +{proj.stack.length - 4}
                        </span>
                      )}
                    </div>
                  </div>
                </button>
              </SwiperSlide>
            );
          })}
        </Swiper>
      </div>
    </Section>
  );
});

ProjectsSection.displayName = 'ProjectsSection';

export default ProjectsSection;
