import React, {useEffect, useState, useRef} from "react";
import './Navbar.css';
import ThemeToggle from '../ThemeToggle/ThemeToggle';
import LanguageToggle from '../LanguageToggle/LanguageToggle';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

export default function NavbarA({logo, scrollToSection, onRef}) {

    const navbarRef = useRef(null);
    const { lang } = useLanguage();
    const t = content[lang].nav;

    const [isMenuOpen, setIsMenuOpen] = useState(false);

    const navItems = [
        { key: 'about', label: t.about },
        { key: 'experience', label: t.experience },
        { key: 'education', label: t.education },
        { key: 'projects', label: t.projects },
        { key: 'skills', label: t.skills },
    ];

    const handleClick = (sectionName) => {
        setIsMenuOpen(false);
        scrollToSection(sectionName);
    }

    const toggleMenu = () => {
        setIsMenuOpen(!isMenuOpen);
    }

    useEffect(() => {
        const handleResize = () => {
            if(window.innerWidth > 1200) {
                setIsMenuOpen(false);
            }
        };
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    },[]);

    useEffect(() => {
        // Prevent body scroll when menu is open
        if(isMenuOpen) {
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'visible';
        }

        return () => {
            document.body.style.overflow = 'visible';
        };
    }, [isMenuOpen]);

    useEffect(() => {
        // Close menu on Escape key press
        const handleEscape = (e) => {
            if (e.key === 'Escape' && isMenuOpen) {
                setIsMenuOpen(false);
            }
        };

        window.addEventListener('keydown', handleEscape);
        return () => window.removeEventListener('keydown', handleEscape);
    }, [isMenuOpen]);

    useEffect(() => {
        if (onRef) {
            onRef(navbarRef);
        }
    }, [onRef]);

    return (
        <nav ref={navbarRef} className="navbar">
            <div
                className={`navbar-menu ${isMenuOpen ? 'open' : ''}`}
                onClick={() => setIsMenuOpen(false)}
                role="dialog"
                aria-modal={isMenuOpen}
                aria-hidden={!isMenuOpen}
            >
                <ul onClick={(e) => e.stopPropagation()}>
                    {navItems.map((item) => (
                        <li key={item.key}>
                            <p onClick={() => handleClick(item.key)} aria-label={`Navigate to ${item.label}`}>{item.label}</p>
                        </li>
                    ))}
                </ul>
            </div>

            <div className="navbar-logo">
                <img src={logo} alt="Dvir Magen Logo" onClick={() => handleClick('topLine')}/>
            </div>

            <div className="navbar-actions">
                <LanguageToggle />
                <ThemeToggle />
                <div
                    className={`hamburger-menu ${isMenuOpen ? 'open' : ''}`}
                    onClick={toggleMenu}
                    aria-label="Toggle navigation menu"
                >
                    <div className="line"></div>
                    <div className="line"></div>
                    <div className="line"></div>
                </div>
            </div>
        </nav>
    );
}
