import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ArrowLeft, Github, ExternalLink } from 'lucide-react';
import { CORE_PROJECTS } from '../constants';
import { useLanguage } from '../contexts/LanguageContext';
import content from '../i18n/content';
import './ProjectDetail.css';

const ProjectDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const { lang } = useLanguage();

  const projectData = CORE_PROJECTS[id];
  const projectContent = content[lang]?.projects?.items?.[id];

  if (!projectData || !projectContent) {
    return (
      <div className="project-detail-not-found">
        <p>Project not found.</p>
        <button onClick={() => navigate('/')} className="project-detail-back">
          <ArrowLeft size={18} />
          Back to portfolio
        </button>
      </div>
    );
  }

  const t = content[lang].projects;

  return (
    <div className="project-detail-page">
      <div className="project-detail-container">
        <button
          className="project-detail-back"
          onClick={() => navigate(-1)}
          aria-label="Go back"
        >
          <ArrowLeft size={18} />
          <span>{lang === 'he' ? 'חזרה' : 'Back'}</span>
        </button>

        <div className="project-detail-hero">
          <div className="project-detail-img-placeholder">
            <span className="project-detail-img-label">
              {lang === 'he' ? 'תמונת פרויקט' : 'Project Preview'}
            </span>
          </div>
        </div>

        <div className="project-detail-body">
          <h1 className="project-detail-title">{projectContent.title}</h1>
          <p className="project-detail-description">{projectContent.description}</p>

          {projectContent.achievements?.length > 0 && (
            <div className="project-detail-section">
              <h2 className="project-detail-section-heading">{t.keyAchievements}</h2>
              <ul className="project-detail-achievements">
                {projectContent.achievements.map((item, i) => (
                  <li key={i}>{item}</li>
                ))}
              </ul>
            </div>
          )}

          {projectData.stack?.length > 0 && (
            <div className="project-detail-section">
              <h2 className="project-detail-section-heading">{t.techStack}</h2>
              <div className="project-detail-stack">
                {projectData.stack.map((tech) => (
                  <span className="project-detail-tag" key={tech}>{tech}</span>
                ))}
              </div>
            </div>
          )}

          {projectData.url && (
            <div className="project-detail-links">
              <a
                href={projectData.url}
                target="_blank"
                rel="noopener noreferrer"
                className="project-detail-github-link"
              >
                <Github size={18} />
                <span>{lang === 'he' ? 'צפייה ב-GitHub' : 'View on GitHub'}</span>
                <ExternalLink size={14} />
              </a>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProjectDetail;
