import './Header.css';
import { forwardRef } from 'react';
import ResumeHeader from '../ResumeHeader/ResumeHeader';
import HeroContactBar from '../HeroContactBar/HeroContactBar';
import VideoScrollHero from '../VideoScrollHero/VideoScrollHero';
import { CONNECTION_DATA } from '../../constants';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

const Header = forwardRef((props, ref) => {
    const { lang } = useLanguage();
    const t = content[lang].hero;

    return (
        <VideoScrollHero ref={ref}>
            <ResumeHeader
                name={t.name}
                tagline={t.tagline}
                badges={t.badges}
            />
            <HeroContactBar
                email="Dvirmagen@gmail.com"
                links={{
                    github: CONNECTION_DATA.github,
                    linkedin: CONNECTION_DATA.linkedin
                }}
                labels={{
                    messageBtn: t.messageBtn,
                    downloadCv: t.downloadCv,
                    copied: t.copied,
                }}
            />
        </VideoScrollHero>
    );
});

Header.displayName = 'Header';

export default Header;
