import React from 'react';
import Section from '../Section/Section';
import './About.css';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

const SLASHIN_TAG = /<slashin>(.*?)<\/slashin>/;

/**
 * Renders a paragraph string, turning a `<slashin>label</slashin>` marker
 * into a real link to the Slash-in website, without using raw HTML injection.
 */
const renderParagraph = (text) => {
  const match = text.match(SLASHIN_TAG);
  if (!match) return text;

  const [fullMatch, label] = match;
  const index = text.indexOf(fullMatch);
  const before = text.slice(0, index);
  const after = text.slice(index + fullMatch.length);

  return (
    <>
      {before}
      <a
        href="https://slash-in.com"
        target="_blank"
        rel="noopener noreferrer"
        className="slash-in-link"
        aria-label="Visit Slash-in website"
      >
        {label}
      </a>
      {after}
    </>
  );
};

/**
 * About section component
 */
const About = React.forwardRef((props, ref) => {
  const { lang } = useLanguage();
  const t = content[lang].about;

  return (
    <Section id="about" title={t.sectionTitle} ref={ref}>
      <div className="about-content">
        <div className="about-text">
          {t.paragraphs.map((paragraph, index) => (
            <p key={index}>{renderParagraph(paragraph)}</p>
          ))}
        </div>
        {t.stats && t.stats.length > 0 && (
          <div className="about-stats">
            {t.stats.map((stat) => (
              <div className="about-stat-card" key={stat.label}>
                <span className="about-stat-value">{stat.value}</span>
                <span className="about-stat-label">{stat.label}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </Section>
  );
});

About.displayName = 'About';

export default About;
