import React from 'react';
import Section from '../Section/Section';
import TimelineItem from '../TimelineItem/TimelineItem';
import { EDUCATION_DATA } from '../../constants';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

/**
 * Education section component - styled identically to Experience section
 */
const EducationSection = React.forwardRef((props, ref) => {
    const { lang } = useLanguage();
    const t = content[lang].education;

    return (
        <Section id="education" title={t.sectionTitle} ref={ref}>
            {EDUCATION_DATA.map((edu) => {
                const localized = t.items[edu.id] || {};
                return (
                    <TimelineItem
                        key={edu.id}
                        title={localized.title}
                        organization={localized.academy}
                        period={edu.years}
                    />
                );
            })}
        </Section>
    );
});

EducationSection.displayName = 'EducationSection';

export default EducationSection;
