import './QuickRoll.css';
import { User, Zap, Rocket, GraduationCap, Briefcase } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

export default function QuickRoll({scrollToSection}){
    const { lang } = useLanguage();
    const t = content[lang];

    const handleClick = (sectionName) => {
        scrollToSection(sectionName);
    }

    const links = [
        { key: 'about', label: t.nav.about, icon: <User size={24} /> },
        { key: 'experience', label: t.nav.experience, icon: <Briefcase size={24} /> },
        { key: 'education', label: t.nav.education, icon: <GraduationCap size={24} /> },
        { key: 'projects', label: t.nav.projects, icon: <Rocket size={24} /> },
        { key: 'skills', label: t.nav.skills, icon: <Zap size={24} /> },
    ];

    return(
        <section className="quick-links-section">
            <h2>{t.footer.quickLinksTitle}</h2>
            <ul className="quick-links-list">
                {links.map((link) => (
                    <li className="quick-link-item" key={link.key}>
                        <button
                            className="quick-link-button"
                            onClick={() => handleClick(link.key)}
                            aria-label={`Navigate to ${link.label}`}
                        >
                            <span className="quick-link-icon">{link.icon}</span>
                            <span className="quick-link-text">{link.label}</span>
                        </button>
                    </li>
                ))}
            </ul>
        </section>
    )
}
