import React, { forwardRef, useCallback, useEffect, useRef, useState } from 'react';
import './VideoScrollHero.css';

const VIDEO_SRC = `${process.env.PUBLIC_URL}/videos/hero-scrub.mp4`;
const POSTER_SRC = `${process.env.PUBLIC_URL}/videos/hero-scrub-poster.jpg`;
const MOBILE_QUERY = '(max-width: 820px)';

/**
 * VideoScrollHero — on desktop/trackpad viewports, a pinned full-viewport
 * panel whose background video is "scrubbed" (currentTime driven directly by
 * scroll position) rather than played back in real time. On small/touch
 * screens (and for prefers-reduced-motion) it falls back to a normal,
 * non-pinned section with the video simply looping — pinning tall content
 * inside 100vh on a phone is what caused the overlap/empty-gap bugs, and
 * scroll-scrubbing doesn't read well with touch-momentum scrolling anyway.
 */
const VideoScrollHero = forwardRef(({ children }, ref) => {
  const wrapperRef = useRef(null);
  const videoRef = useRef(null);
  const [reduceMotion, setReduceMotion] = useState(false);
  const [isMobile, setIsMobile] = useState(false);
  const [progress, setProgress] = useState(0);
  const [videoFailed, setVideoFailed] = useState(false);

  const simpleMode = reduceMotion || isMobile;

  const setRefs = useCallback((node) => {
    wrapperRef.current = node;
    if (typeof ref === 'function') ref(node);
    else if (ref) ref.current = node;
  }, [ref]);

  // Watch prefers-reduced-motion + viewport size
  useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
      return undefined;
    }
    const motionMq = window.matchMedia('(prefers-reduced-motion: reduce)');
    const mobileMq = window.matchMedia(MOBILE_QUERY);
    setReduceMotion(motionMq.matches);
    setIsMobile(mobileMq.matches);

    const motionHandler = (e) => setReduceMotion(e.matches);
    const mobileHandler = (e) => setIsMobile(e.matches);

    motionMq.addEventListener ? motionMq.addEventListener('change', motionHandler) : motionMq.addListener(motionHandler);
    mobileMq.addEventListener ? mobileMq.addEventListener('change', mobileHandler) : mobileMq.addListener(mobileHandler);

    return () => {
      motionMq.removeEventListener ? motionMq.removeEventListener('change', motionHandler) : motionMq.removeListener(motionHandler);
      mobileMq.removeEventListener ? mobileMq.removeEventListener('change', mobileHandler) : mobileMq.removeListener(mobileHandler);
    };
  }, []);

  // Prime the video so browsers actually decode/paint a frame instead of
  // sitting on the poster forever (many mobile + some desktop browsers won't
  // render scrubbed frames until playback has started at least once).
  useEffect(() => {
    const video = videoRef.current;
    if (!video) return undefined;

    let cancelled = false;
    const primeVideo = () => {
      if (cancelled) return;
      const playResult = video.play();
      if (playResult && typeof playResult.then === 'function') {
        playResult
          .then(() => {
            if (cancelled) return;
            if (simpleMode) return; // let it keep looping/playing normally
            video.pause();
          })
          .catch(() => {
            // Autoplay blocked — scrubbing will still work once the user
            // interacts with the page (scroll counts as a gesture in most
            // browsers), so this is a soft failure.
          });
      }
    };

    if (video.readyState >= 2) {
      primeVideo();
    } else {
      video.addEventListener('loadeddata', primeVideo, { once: true });
    }

    return () => {
      cancelled = true;
      video.removeEventListener('loadeddata', primeVideo);
    };
  }, [simpleMode]);

  useEffect(() => {
    if (simpleMode) return undefined;
    const video = videoRef.current;
    const wrapper = wrapperRef.current;
    if (!video || !wrapper) return undefined;

    let rafId = null;
    let duration = 0;

    const handleLoadedMetadata = () => {
      duration = video.duration || 0;
    };
    video.addEventListener('loadedmetadata', handleLoadedMetadata);
    // In case metadata is already available (cached video)
    if (video.readyState >= 1) handleLoadedMetadata();

    const updateScrub = () => {
      rafId = null;
      const rect = wrapper.getBoundingClientRect();
      const scrollableRange = wrapper.offsetHeight - window.innerHeight;
      const scrolled = -rect.top;
      const rawProgress = scrollableRange > 0 ? scrolled / scrollableRange : 0;
      const clamped = Math.min(1, Math.max(0, rawProgress));
      setProgress(clamped);

      if (duration > 0 && !Number.isNaN(duration)) {
        const targetTime = clamped * duration;
        if (Math.abs(video.currentTime - targetTime) > 0.03) {
          video.currentTime = targetTime;
        }
      }
    };

    updateScrub();
    const onScroll = () => {
      if (rafId == null) {
        rafId = requestAnimationFrame(updateScrub);
      }
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);

    return () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      video.removeEventListener('loadedmetadata', handleLoadedMetadata);
      if (rafId != null) cancelAnimationFrame(rafId);
    };
  }, [simpleMode]);

  return (
    <div className={`video-scrub-wrapper ${simpleMode ? 'no-scrub' : ''}`} ref={setRefs}>
      <div className="video-scrub-sticky">
        {videoFailed ? (
          <div className="video-scrub-placeholder" aria-hidden="true" />
        ) : (
          <video
            ref={videoRef}
            className="video-scrub-media"
            src={VIDEO_SRC}
            poster={POSTER_SRC}
            muted
            playsInline
            loop={simpleMode}
            autoPlay={simpleMode}
            preload="auto"
            aria-hidden="true"
            tabIndex={-1}
            onError={() => setVideoFailed(true)}
          />
        )}
        <div className="video-scrub-overlay" aria-hidden="true" />
        <div className="video-scrub-content">
          {children}
        </div>
        <div
          className={`video-scrub-hint ${!simpleMode && progress > 0.08 ? 'is-hidden' : ''}`}
          aria-hidden="true"
        >
          <span className="video-scrub-hint-chevron" />
        </div>
        {!simpleMode && (
          <div className="video-scrub-progress" aria-hidden="true">
            <div className="video-scrub-progress-bar" style={{ transform: `scaleX(${progress})` }} />
          </div>
        )}
      </div>
    </div>
  );
});

VideoScrollHero.displayName = 'VideoScrollHero';

export default VideoScrollHero;
