import React, { useState } from 'react';
import '../ResumeHeader/ResumeHeader.css';
import '../ContactButton/ContactButton.css';
import './HeroContactBar.css';
import { CONNECTION_DATA } from '../../constants';
import ContactButton from '../ContactButton/ContactButton';
import { MessageCircle, Download } from 'lucide-react';

/**
 * HeroContactBar — the row of contact actions (message, email, GitHub,
 * LinkedIn, CV) shown directly under the skill badges inside the video hero.
 */
const HeroContactBar = ({ email, links = {}, labels = {} }) => {
  const [emailCopied, setEmailCopied] = useState(false);

  const {
    messageBtn = 'Send me message',
    downloadCv = 'Download CV',
    copied = 'Copied!',
  } = labels;

  const handleEmailClick = async (e) => {
    e.preventDefault();
    if (email) {
      try {
        await navigator.clipboard.writeText(email);
        setEmailCopied(true);
        setTimeout(() => {
          setEmailCopied(false);
        }, 2000);
      } catch (err) {
        console.error('Failed to copy email:', err);
      }
    }
  };

  return (
    <section className="hero-contact-bar">
      <div className="resume-contact">
        <ContactButton
          label={messageBtn}
          buttonClassName="contact-link contact-message"
          icon={<MessageCircle size={20} />}
        />
        {email && (
          <div className="email-button-wrapper">
            <button
              onClick={handleEmailClick}
              className="contact-link contact-email"
              aria-label={`Copy email ${email}`}
              type="button"
            >
              <img
                src={CONNECTION_DATA.email.logo}
                alt="Email icon"
                className="contact-icon-img"
              />
              <span className="contact-text">{email}</span>
            </button>
            {emailCopied && <span className="copy-tooltip">{copied}</span>}
          </div>
        )}
        {links.github && (
          <a
            href={links.github.url}
            target="_blank"
            rel="noopener noreferrer"
            className="contact-link contact-github"
            aria-label="GitHub profile"
          >
            <img
              src={links.github.logo}
              alt="GitHub icon"
              className="contact-icon-img"
            />
            <span className="contact-text">GitHub</span>
          </a>
        )}
        {links.linkedin && (
          <a
            href={links.linkedin.url}
            target="_blank"
            rel="noopener noreferrer"
            className="contact-link contact-linkedin"
            aria-label="LinkedIn profile"
          >
            <img
              src={links.linkedin.logo}
              alt="LinkedIn icon"
              className="contact-icon-img"
            />
            <span className="contact-text">LinkedIn</span>
          </a>
        )}
        <a
          href={CONNECTION_DATA.cv.url}
          target="_blank"
          rel="noopener noreferrer"
          className="contact-link contact-cv"
          aria-label={downloadCv}
        >
          <span className="contact-button-icon">
            <Download size={20} />
          </span>
          <span className="contact-text">{downloadCv}</span>
        </a>
      </div>
    </section>
  );
};

export default HeroContactBar;
