import { CONNECTION_DATA } from "../../constants";
import { GitHub, LinkedIn, Download, Email, ContentCopy } from '@mui/icons-material';
import './Connect.css';
import { useState, useEffect } from 'react';
import { sendContact } from '../../utils/sendEmail';
import '../ContactButton/ContactButton.css';
import { MessageCircle } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

export default function Connect(){
    const { lang } = useLanguage();
    const t = content[lang].footer;
    const heroT = content[lang].hero;
    const m = content[lang].modal;
    const [isMessageModalOpen, setIsMessageModalOpen] = useState(false);
    const [emailCopied, setEmailCopied] = useState(false);
    const [status, setStatus] = useState('idle'); // 'idle' | 'sending' | 'success' | 'error'
    const [errorMsg, setErrorMsg] = useState('');
    const [fromName, setFromName] = useState('');
    const [messageContent, setMessageContent] = useState('');
    const [website, setWebsite] = useState(''); // Honeypot field
    const [errors, setErrors] = useState({ fromName: '', messageContent: '' });
    const [touched, setTouched] = useState({ fromName: false, messageContent: false });

    // Prevent body scrolling when modal is open
    useEffect(() => {
        if (isMessageModalOpen) {
            // Save current scroll position
            const scrollY = window.scrollY;
            // Save current overflow values
            const originalBodyOverflow = document.body.style.overflow;
            const originalHtmlOverflow = document.documentElement.style.overflow;
            const originalBodyPosition = document.body.style.position;
            const originalBodyTop = document.body.style.top;
            const originalBodyWidth = document.body.style.width;
            
            // Prevent scrolling on both body and html
            document.body.style.overflow = 'hidden';
            document.documentElement.style.overflow = 'hidden';
            document.body.style.position = 'fixed';
            document.body.style.top = `-${scrollY}px`;
            document.body.style.width = '100%';
            
            // Prevent scroll events
            const preventScroll = (e) => {
                e.preventDefault();
                e.stopPropagation();
                return false;
            };
            
            document.addEventListener('wheel', preventScroll, { passive: false });
            document.addEventListener('touchmove', preventScroll, { passive: false });
            document.addEventListener('scroll', preventScroll, { passive: false });
            
            // Cleanup: restore scrolling when modal closes
            return () => {
                document.body.style.overflow = originalBodyOverflow;
                document.documentElement.style.overflow = originalHtmlOverflow;
                document.body.style.position = originalBodyPosition;
                document.body.style.top = originalBodyTop;
                document.body.style.width = originalBodyWidth;
                
                // Restore scroll position
                window.scrollTo(0, scrollY);
                
                // Remove event listeners
                document.removeEventListener('wheel', preventScroll);
                document.removeEventListener('touchmove', preventScroll);
                document.removeEventListener('scroll', preventScroll);
            };
        }
    }, [isMessageModalOpen]);

    const handleOpenMessageModal = () => {
        setIsMessageModalOpen(true);
        setStatus('idle');
        setErrorMsg('');
        // Reset errors and touched when opening
        setErrors({ fromName: '', messageContent: '' });
        setTouched({ fromName: false, messageContent: false });
    };

    const handleCloseMessageModal = () => {
        setIsMessageModalOpen(false);
        setStatus('idle');
        setErrorMsg('');
        // Reset form state when closing
        setFromName('');
        setMessageContent('');
        setWebsite('');
        setErrors({ fromName: '', messageContent: '' });
        setTouched({ fromName: false, messageContent: false });
    };

    const handleEmailClick = async (e) => {
        e.preventDefault();
        const email = CONNECTION_DATA.email.title;
        try {
            await navigator.clipboard.writeText(email);
            setEmailCopied(true);
            setTimeout(() => {
                setEmailCopied(false);
            }, 2000);
        } catch (err) {
            console.error('Failed to copy email:', err);
        }
    };

    const validateField = (name, value) => {
        const trimmed = value.trim();
        if (!trimmed) {
            if (name === 'fromName') return m.nameRequired;
            if (name === 'messageContent') return m.messageRequired;
        }
        return '';
    };

    const handleBlur = (fieldName) => {
        setTouched({ ...touched, [fieldName]: true });
        const value = fieldName === 'fromName' ? fromName : messageContent;
        const error = validateField(fieldName, value);
        setErrors({ ...errors, [fieldName]: error });
    };

    const handleChange = (fieldName, value) => {
        if (fieldName === 'fromName') {
            setFromName(value);
        } else if (fieldName === 'messageContent') {
            setMessageContent(value);
        }
        // Clear error when user starts typing
        if (touched[fieldName] && errors[fieldName]) {
            const error = validateField(fieldName, value);
            setErrors({ ...errors, [fieldName]: error });
        }
    };

    const handleSubmitMessage = async (event) => {
        event.preventDefault();
        event.stopPropagation();

        // Mark all fields as touched
        setTouched({ fromName: true, messageContent: true });

        // Validate all fields
        const fromNameError = validateField('fromName', fromName);
        const messageContentError = validateField('messageContent', messageContent);

        setErrors({
            fromName: fromNameError,
            messageContent: messageContentError,
        });

        // If there are errors, don't submit
        if (fromNameError || messageContentError) {
            setStatus('error');
            setErrorMsg(m.genericError);
            return;
        }

        // Set sending status
        setStatus('sending');
        setErrorMsg('');

        try {
            const result = await sendContact(fromName, messageContent, website);

            if (result.success) {
                // Show success message
                setStatus('success');
                // Clear form fields
                setFromName('');
                setMessageContent('');
                setWebsite('');
            } else {
                // Show error message
                setStatus('error');
                setErrorMsg(result.error || m.sendFailed);
            }
        } catch (error) {
            console.error('Failed to send contact:', error);
            setStatus('error');
            setErrorMsg(m.sendFailed);
        }
    };

    return(
        <section className="connect-section">
            <h2>{t.connectTitle}</h2>
            <div className="connect-items">
                <button
                    onClick={handleOpenMessageModal}
                    className="connect-link connect-link-email"
                    aria-label="Send a direct message"
                    type="button"
                >
                    <span className="connect-icon">
                        <MessageCircle size={20} />
                    </span>
                    <span className="connect-text">{t.sendMessage}</span>
                </button>
                <button
                    onClick={handleEmailClick}
                    className="connect-link connect-link-email-copy"
                    aria-label={`Copy email ${CONNECTION_DATA.email.title}`}
                    type="button"
                >
                    <span className="connect-icon">
                        <Email fontSize="small" />
                    </span>
                    <span className="connect-text">{CONNECTION_DATA.email.title}</span>
                    <span className="connect-copy-icon">
                        {emailCopied ? (
                            <span className="copied-text">{t.copied}</span>
                        ) : (
                            <ContentCopy fontSize="small" />
                        )}
                    </span>
                </button>
                <a
                    href={CONNECTION_DATA.github.url}
                    rel="noopener noreferrer"
                    target="_blank"
                    className="connect-link"
                    aria-label="GitHub profile"
                >
                    <span className="connect-icon">
                        <GitHub fontSize="small" />
                    </span>
                    <span className="connect-text">{CONNECTION_DATA.github.title}</span>
                </a>
                <a
                    href={CONNECTION_DATA.linkedin.url}
                    rel="noopener noreferrer"
                    target="_blank"
                    className="connect-link"
                    aria-label="LinkedIn profile"
                >
                    <span className="connect-icon">
                        <LinkedIn fontSize="small" />
                    </span>
                    <span className="connect-text">{CONNECTION_DATA.linkedin.title}</span>
                </a>
                <a
                    href={CONNECTION_DATA.cv.url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="connect-link"
                    aria-label={heroT.downloadCv}
                >
                    <span className="connect-icon">
                        <Download fontSize="small" />
                    </span>
                    <span className="connect-text">{heroT.downloadCv}</span>
                </a>
            </div>

            {isMessageModalOpen && (
                <div className="message-modal-backdrop" role="dialog" aria-modal="true" aria-labelledby={status === 'success' ? "message-sent-title" : "connect-send-message-title"}>
                    <div className="message-modal">
                        {status === 'success' ? (
                            <div className="message-modal-success">
                                <div className="message-modal-success-content">
                                    <h3 id="message-sent-title" className="message-modal-success-title">
                                        {m.thankYou}
                                    </h3>
                                    <p className="message-modal-success-message">
                                        {m.successMessage}
                                    </p>
                                </div>
                                <div className="message-modal-actions message-modal-actions-center">
                                    <button
                                        type="button"
                                        className="message-modal-primary"
                                        onClick={handleCloseMessageModal}
                                    >
                                        {m.gotIt}
                                    </button>
                                </div>
                            </div>
                        ) : (
                            <>
                                <div className="message-modal-header">
                                    <h3 id="connect-send-message-title" className="message-modal-title">
                                        {m.title}
                                    </h3>
                                    <button
                                        type="button"
                                        className="message-modal-close"
                                        onClick={handleCloseMessageModal}
                                        aria-label={m.close}
                                        disabled={status === 'sending'}
                                    >
                                        ×
                                    </button>
                                </div>
                                <form className="message-modal-form" onSubmit={handleSubmitMessage} noValidate>
                                    {/* Honeypot field - hidden from users */}
                                    <input
                                        type="text"
                                        name="website"
                                        value={website}
                                        onChange={(e) => setWebsite(e.target.value)}
                                        style={{ display: 'none' }}
                                        autoComplete="off"
                                        tabIndex="-1"
                                        aria-hidden="true"
                                    />
                                    <label className="message-modal-label">
                                        {m.nameLabel}
                                        <input
                                            type="text"
                                            className={`message-modal-input ${touched.fromName && errors.fromName ? 'message-modal-input-error' : ''}`}
                                            placeholder={m.namePlaceholder}
                                            value={fromName}
                                            onChange={(e) => handleChange('fromName', e.target.value)}
                                            onBlur={() => handleBlur('fromName')}
                                            disabled={status === 'sending'}
                                            required
                                        />
                                        {touched.fromName && errors.fromName && (
                                            <span className="message-modal-help-text">{errors.fromName}</span>
                                        )}
                                    </label>
                                    <label className="message-modal-label">
                                        {m.messageLabel}
                                        <textarea
                                            className={`message-modal-textarea ${touched.messageContent && errors.messageContent ? 'message-modal-textarea-error' : ''}`}
                                            placeholder={m.messagePlaceholder}
                                            value={messageContent}
                                            onChange={(e) => handleChange('messageContent', e.target.value)}
                                            onBlur={() => handleBlur('messageContent')}
                                            rows={6}
                                            disabled={status === 'sending'}
                                            required
                                        />
                                        {touched.messageContent && errors.messageContent && (
                                            <span className="message-modal-help-text">{errors.messageContent}</span>
                                        )}
                                    </label>
                                    {status === 'error' && errorMsg && (
                                        <div className="message-modal-error" role="alert">
                                            {errorMsg}
                                        </div>
                                    )}
                                    <div className="message-modal-actions">
                                        <button
                                            type="button"
                                            className="message-modal-secondary"
                                            onClick={handleCloseMessageModal}
                                            disabled={status === 'sending'}
                                        >
                                            {m.cancel}
                                        </button>
                                        <button
                                            type="submit"
                                            className="message-modal-primary"
                                            disabled={status === 'sending'}
                                        >
                                            {status === 'sending' ? m.sending : m.send}
                                        </button>
                                    </div>
                                </form>
                            </>
                        )}
                    </div>
                </div>
            )}
        </section>
    )
}