import React from 'react';
import Section from '../Section/Section';
import TimelineItem from '../TimelineItem/TimelineItem';
import { EXPERIENCE_DATA } from '../../constants';
import { useLanguage } from '../../contexts/LanguageContext';
import content from '../../i18n/content';

/**
 * Experience section component
 */
const ExperienceSection = React.forwardRef((props, ref) => {
    const { lang } = useLanguage();
    const t = content[lang].experience;

    return (
        <Section id="experience" title={t.sectionTitle} ref={ref}>
            {EXPERIENCE_DATA.map((exp) => {
                const localized = t.items[exp.id] || {};
                return (
                    <TimelineItem
                        key={exp.id}
                        title={localized.title}
                        organization={localized.organization}
                        period={exp.period}
                        achievements={localized.achievements}
                        stack={exp.stack}
                        stackLabel={t.stackLabel}
                        visitPrefix={t.visitPrefix}
                        url={exp.url}
                    />
                );
            })}
        </Section>
    );
});

ExperienceSection.displayName = 'ExperienceSection';

export default ExperienceSection;
